SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
SET time_zone = "+00:00";
SET FOREIGN_KEY_CHECKS = 0;

-- Struktur tabel
--

CREATE TABLE `jadwal_pelajaran` (
  `id` int NOT NULL,
  `rombel_id` int NOT NULL,
  `id_tahun_ajaran` int DEFAULT NULL,
  `semester` enum('Ganjil','Genap') DEFAULT NULL,
  `guru_id` int DEFAULT NULL COMMENT 'Bisa NULL jika TAHFIZH/BPI',
  `mapel_id` int DEFAULT NULL,
  `kode_jadwal_excel` varchar(100) DEFAULT NULL COMMENT 'Menyimpan kode asli: IPS/AAM, dll',
  `hari` varchar(20) NOT NULL,
  `jam_ke` varchar(20) NOT NULL COMMENT 'Les 1, 2, 3 atau ISTIRAHAT',
  `jam_mulai` time NOT NULL,
  `jam_selesai` time NOT NULL,
  `jenis_jadwal` enum('Reguler','Jumat BPI','Jumat Non-BPI') NOT NULL DEFAULT 'Reguler',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

